        }

        /* Pull-to-refresh indikátor */
        .pull-refresh {
            position: fixed;
            top: -60px;
            left: 50%;
            transform: translateX(-50%);
            width: 40px;
            height: 40px;
            background: var(--glass);
            border-radius: 50%;
            display: flex;
